def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    prev_bids = []
    urgent_opp = 0
    affordable_caps = []

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(bid)
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                urgent_opp += 1
            affordable_caps.append(min(opp.get('budget', 0), opp.get('daily_salary', DAILY_SALARY) * 2.2))

    if budget <= 0:
        return 0.0

    if not alive:
        return float(min(budget, DAILY_SALARY * 0.35))

    high_supply = supply >= 20
    low_supply = supply <= 17

    top_prev = max(prev_bids) if prev_bids else DAILY_SALARY * 0.8
    top_affordable = max(affordable_caps) if affordable_caps else top_prev

    danger = 0
    if hp <= 2:
        danger += 3
    elif hp <= 4:
        danger += 2
    elif hp <= 6:
        danger += 1

    if no_water >= 2:
        danger += 3
    elif no_water >= 1:
        danger += 2

    if low_supply:
        danger += 1
    if urgent_opp >= 2:
        danger += 1

    if danger >= 5:
        target = max(DAILY_SALARY * 1.45, min(top_affordable + 2.0, budget))
    elif danger >= 3:
        target = max(DAILY_SALARY * 1.05, min(top_prev + 1.5, top_affordable + 1.0, budget))
    else:
        if high_supply and hp >= 7 and no_water == 0:
            target = DAILY_SALARY * 0.38
        elif top_prev > DAILY_SALARY * 1.8:
            target = DAILY_SALARY * 0.42
        else:
            target = max(DAILY_SALARY * 0.52, min(top_prev * 0.72, DAILY_SALARY * 0.9))

    reserve_floor = DAILY_SALARY * 2.2 if hp > 3 else DAILY_SALARY * 1.0
    if budget > reserve_floor:
        target = min(target, budget - reserve_floor + DAILY_SALARY * 0.25)

    if hp <= 2 or no_water >= 2:
        target = max(target, DAILY_SALARY * 1.1)

    target = max(0.0, min(float(target), float(budget)))
    return float(round(target, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        return float(min(budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from previous_trace for immediate reaction.
    prev_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    avg_prev_bid = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    # Estimate how many water units are likely needed today to avoid hp loss.
    # If supply is low, water is scarcer -> bid higher.
    supply_ratio = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_ratio = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    supply_ratio = max(0.0, min(1.0, supply_ratio))

    # Base bid: mid level. Raise when supply is low (scarce) or my hp is critical.
    # Also raise if yesterday saw very high bids (indicating aggressive competition).
    critical = (hp <= 2) or (no_water_days >= 2)

    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # Opponents were extremely aggressive yesterday; don't overpay to extinction, but ensure contention.
        base = DAILY_SALARY * (0.45 if supply_ratio > 0.5 else 0.65)
        if critical:
            base = DAILY_SALARY * 0.85
    elif avg_prev_bid >= DAILY_SALARY * 0.9:
        base = DAILY_SALARY * (0.4 if supply_ratio > 0.6 else 0.6)
        if critical:
            base = DAILY_SALARY * 0.75
    else:
        base = DAILY_SALARY * (0.35 if supply_ratio > 0.6 else 0.55)
        if critical:
            base = DAILY_SALARY * 0.7

    # Convert base into a bid cap that scales with remaining budget.
    # Keep a safety reserve to survive multiple days.
    safety_fraction = 0.25 if day < 7 else 0.15
    max_affordable = budget * (1.0 - safety_fraction)

    # If budget is very low, still bid enough to avoid immediate failure.
    if budget <= DAILY_SALARY * 0.2:
        bid = min(budget, DAILY_SALARY * 0.5)
        return float(max(0.0, bid))

    # Final bid: add a small increment over average aggression to beat likely bids.
    bid = base
    if prev_bids:
        # Use a fraction of the highest previous bid as a pressure signal.
        bid = max(bid, min(budget, highest_prev_bid * (0.55 if supply_ratio > 0.5 else 0.75)))

    # If I'm healthy, avoid burning too much; if low hp, push.
    if hp >= 6 and not critical:
        bid *= 0.85
    elif hp <= 3 or critical:
        bid *= 1.05

    bid = min(bid, max_affordable)
    bid = max(0.0, bid)

    # Ensure integer-free float output is acceptable; return float.
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        # If no opponents, bid minimally to secure water, as supply is always sufficient.
        return min(my_status['budget'], 1.0)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Base bid if no specific conditions apply
    base_bid = DAILY_SALARY * 0.55

    # High priority: If my HP is critically low, bid aggressively to survive.
    if my_status['hp'] <= 2:
        return min(my_status['budget'], DAILY_SALARY * 0.9)

    # React to yesterday's highest bid from opponents
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        # If opponents were very aggressive yesterday (e.g., highest bid >= 85% of daily salary)
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            if my_status['hp'] > 3: # My HP is okay, try to save by underbidding
                return min(my_status['budget'], DAILY_SALARY * 0.3)
            else: # My HP is low or moderate, must compete fiercely
                return min(my_status['budget'], DAILY_SALARY * 0.95)
        # If opponents were moderately aggressive or less
        else:
            # Try to bid slightly above the highest previous bid to secure water,
            # ensuring it's at least a reasonable base amount (50% of daily salary).
            return min(my_status['budget'], max(DAILY_SALARY * 0.5, highest_prev_bid + 1.5))

    # Fallback for Day 1 or if no previous bids were recorded for other reasons
    return min(my_status['budget'], base_bid)

def get_bid(day_context, my_status, opponents_status):
